const c = await api.get("/customers");
const m = await api.get("/mails");
const delayed = new Set(c.items.filter(x => x.order && x.order.status === "delayed").map(x => x.id));
const complaintCustomers = new Set(m.items.filter(x => x.label === "complaint" && x.customer_id).map(x => x.customer_id));
const result = [...delayed].filter(id => complaintCustomers.has(id));
return { customersFetched: c.items.length, customersTotal: c.count, mailsFetched: m.items.length, mailsTotal: m.count, result };
